/* B"H */
#include "include/awts_native_browser.h"

static float sx(const AwtsBrowserState* s, int px) { return ((float)px / (float)s->width) * 2.0f - 1.0f; }
static float sy(const AwtsBrowserState* s, int py) { return 1.0f - ((float)py / (float)s->height) * 2.0f; }
static float sw(const AwtsBrowserState* s, int px) { return ((float)px / (float)s->width) * 2.0f; }
static float sh(const AwtsBrowserState* s, int py) { return ((float)py / (float)s->height) * 2.0f; }

static void rect(float x, float y, float w, float h, float r, float g, float b) {
  glColor3f(r, g, b);
  glBegin(GL_QUADS);
    glVertex2f(x, y); glVertex2f(x + w, y); glVertex2f(x + w, y + h); glVertex2f(x, y + h);
  glEnd();
}

static void outline(float x, float y, float w, float h, float r, float g, float b) {
  glColor3f(r, g, b);
  glBegin(GL_LINE_LOOP);
    glVertex2f(x, y); glVertex2f(x + w, y); glVertex2f(x + w, y + h); glVertex2f(x, y + h);
  glEnd();
}

static void bar(float x, float y, float w, float value, float r, float g, float b) {
  rect(x, y, w * value, 0.035f, r, g, b);
  outline(x, y, w, 0.035f, 0.35f, 0.42f, 0.55f);
}

void awts_font_init(AwtsBrowserState* state, HDC dc) {
  if (state->font.ready) return;
  state->font.base = glGenLists(256);
  state->font.font = CreateFontA(-16, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE, ANSI_CHARSET, OUT_TT_PRECIS, CLIP_DEFAULT_PRECIS, ANTIALIASED_QUALITY, FF_DONTCARE | DEFAULT_PITCH, "Consolas");
  if (!state->font.font) state->font.font = CreateFontA(-16, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE, ANSI_CHARSET, OUT_TT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, FF_DONTCARE | DEFAULT_PITCH, "Segoe UI");
  SelectObject(dc, state->font.font);
  state->font.ready = wglUseFontBitmapsA(dc, 0, 255, state->font.base) ? 1 : 0;
}

void awts_font_destroy(AwtsBrowserState* state) {
  if (state->font.ready) glDeleteLists(state->font.base, 256);
  if (state->font.font) DeleteObject(state->font.font);
  state->font.ready = 0; state->font.font = NULL; state->font.base = 0;
}

void awts_draw_text(AwtsBrowserState* state, float x, float y, const char* text, float r, float g, float b) {
  if (!state->font.ready || !text) return;
  glColor3f(r, g, b);
  glRasterPos2f(x, y);
  glPushAttrib(GL_LIST_BIT);
  glListBase(state->font.base);
  glCallLists((GLsizei)strlen(text), GL_UNSIGNED_BYTE, text);
  glPopAttrib();
}

static void draw_address_text(AwtsBrowserState* state, float x, float y) {
  char shown[170];
  snprintf(shown, sizeof(shown), "%s%s", state->url, state->focusedAddress && ((state->frames / 30) % 2 == 0) ? "|" : "");
  awts_draw_text(state, x + 0.012f, y + 0.030f, shown, 0.82f, 0.90f, 1.0f);
}

static void draw_webgl_canvas(AwtsBrowserState* state, float x, float y, float w, float h) {
  rect(x, y, w, h, 0.02f, 0.045f, 0.075f);
  outline(x, y, w, h, 0.25f, 0.55f, 0.88f);
  awts_draw_text(state, x + 0.025f, y + h - 0.055f, "canvas#stage WebGL", 0.56f, 0.90f, 1.0f);
  float cx = x + w * 0.50f, cy = y + h * 0.46f, s = h * 0.27f;
  glBegin(GL_TRIANGLES);
    glColor3f(1.0f, 0.28f, 0.10f); glVertex2f(cx - s, cy - s * 0.70f);
    glColor3f(0.10f, 0.90f, 0.38f); glVertex2f(cx + s, cy - s * 0.70f);
    glColor3f(0.30f, 0.45f, 1.0f); glVertex2f(cx, cy + s);
  glEnd();
}

static void draw_dom(AwtsBrowserState* state) {
  float panelX = -0.92f, panelY = -0.82f, panelW = 1.84f, panelH = 1.42f;
  rect(panelX, panelY, panelW, panelH, 0.025f, 0.034f, 0.060f);
  outline(panelX, panelY, panelW, panelH, 0.20f, 0.34f, 0.58f);
  awts_draw_text(state, -0.84f, 0.515f, state->pageTitle[0] ? state->pageTitle : "browser-shell.merkava", 0.62f, 0.78f, 1.0f);
  awts_draw_text(state, -0.84f, 0.460f, state->pageKind[0] ? state->pageKind : "native DOM", 0.70f, 0.76f, 0.86f);

  if (state->dom.count <= 0) {
    awts_draw_text(state, -0.60f, 0.170f, "No parsed DOM yet", 0.9f, 0.6f, 0.45f);
    return;
  }

  float y = 0.360f;
  for (int i = 0; i < state->dom.count && i < 16; i++) {
    AwtsDomNode* n = &state->dom.nodes[i];
    float x = -0.78f + n->depth * 0.055f;
    if (!strcmp(n->tag, "canvas")) {
      draw_webgl_canvas(state, -0.54f, -0.18f, 1.08f, 0.46f);
      y -= 0.055f;
      continue;
    }
    if (!strcmp(n->tag, "button")) {
      rect(-0.30f, -0.52f, 0.24f, 0.085f, 0.14f, 0.30f, 0.60f);
      outline(-0.30f, -0.52f, 0.24f, 0.085f, 0.55f, 0.78f, 1.0f);
      awts_draw_text(state, -0.255f, -0.485f, n->text[0] ? n->text : "draw", 0.86f, 0.93f, 1.0f);
      continue;
    }
    if (!strcmp(n->tag, "output")) {
      rect(0.02f, -0.52f, 0.78f, 0.085f, 0.08f, 0.12f, 0.18f);
      outline(0.02f, -0.52f, 0.78f, 0.085f, 0.35f, 0.50f, 0.72f);
      awts_draw_text(state, 0.045f, -0.485f, n->text[0] ? n->text : state->statusText, 0.78f, 0.86f, 1.0f);
      continue;
    }
    char line[260];
    if (!strcmp(n->tag, "#text")) snprintf(line, sizeof(line), "%s", n->text);
    else snprintf(line, sizeof(line), "<%s%s%s>", n->tag, n->id[0] ? "#" : "", n->id);
    awts_draw_text(state, x, y, line, !strcmp(n->tag, "main") ? 0.80f : 0.72f, 0.88f, 1.0f);
    y -= 0.052f;
  }

  bar(-0.82f, -0.74f, 0.45f, state->webgl.viewport ? 1.0f : 0.08f, 0.35f, 0.65f, 1.0f);
  bar(-0.28f, -0.74f, 0.45f, state->webgl.clearColor ? 1.0f : 0.08f, 0.30f, 0.95f, 0.55f);
  bar(0.26f, -0.74f, 0.45f, state->webgl.drawArrays ? 1.0f : 0.08f, 1.0f, 0.55f, 0.30f);
  awts_draw_text(state, -0.82f, -0.795f, "viewport", 0.58f, 0.72f, 1.0f);
  awts_draw_text(state, -0.28f, -0.795f, "clearColor", 0.58f, 1.0f, 0.76f);
  awts_draw_text(state, 0.26f, -0.795f, "drawArrays", 1.0f, 0.70f, 0.52f);
}

void awts_draw_native_browser(AwtsBrowserState* state) {
  glViewport(0, 0, state->width, state->height);
  glClearColor(0.012f, 0.016f, 0.035f, 1.0f);
  glClear(GL_COLOR_BUFFER_BIT);

  float chromeY = sy(state, 34);
  float chromeH = -sh(state, 72);
  rect(-0.96f, chromeY, 1.92f, chromeH, 0.045f, 0.055f, 0.085f);
  rect(-0.90f, sy(state, 56), 0.08f, -sh(state, 18), 0.95f, 0.25f, 0.22f);
  rect(-0.79f, sy(state, 56), 0.08f, -sh(state, 18), 0.95f, 0.72f, 0.18f);
  rect(-0.68f, sy(state, 56), 0.08f, -sh(state, 18), 0.18f, 0.82f, 0.35f);

  float ax = sx(state, 238), ay = sy(state, 77), aw = sw(state, 635), ah = -sh(state, 16);
  rect(ax, ay, aw, ah, state->hoverAddress ? 0.13f : 0.08f, 0.12f, 0.19f);
  outline(ax, ay, aw, ah, state->focusedAddress ? 0.60f : 0.30f, 0.70f, 1.0f);
  draw_address_text(state, ax, ay);

  awts_draw_text(state, -0.90f, 0.745f, "B'H Merkava Browser", 0.78f, 0.90f, 1.0f);
  awts_draw_text(state, -0.90f, 0.690f, state->statusText, 0.55f, 0.95f, 0.68f);

  draw_dom(state);
}
